***********************************************************************************************************************************	     Scrap Manager*	     RAM Based Tool*	      Version 2.0**** August 29, 1986	Steven E. Glass** October 27, 1986	Steven E. Glass**     Calls GetScrapCount and GetScrapState were missing.** April 10, 1987	Steven E. Glass**     BootInit and reset were incrementing busy flag.** April 16, 1987	Steven E. Glass, Dan D. Hitchens**     DisposeAllScraps wasn't disposing last handle.*     PutScrap wasn't always reporting an error when out*     of memory.** March 02, 1988	     v1.3d1     Harry Yee*     The scrap manager has been converted over to the*     MPW MAX development system.*     The scrap manager has also been made rommable.** March 22, 1988	     v1.3d1     Steven Glass**     Only the calltable is exported.	(no code changes)*** March 23, 1988	     v1.3d2     Steven Glass** The routine InitScrapInfo assumed that the OS was* available for use.  When this code runs in ROM,* InitScrapInfo is called from ScrapBootInit long before* the OS is loaded.  I changed InitScrapInfo to check to* see if the OS was available before making an OS call.* The OS call being made is GetFileInfo which is checking* to see if the clipboard file is present (i.e. whether* the scrap is on disk or in memory. If the OS is not* present then the code to check if the scrap is on disk* is skipped and it is assumed that the scrap is in* memory.** Other routines will have to be checked to see what* should happen under similar circumstances.** April 29, 1988	     v1.3d3     Harry Yee** ScrapReset would always fail because the a-reg was not* zero upon exit from ScrapReset, even though no error* had ocurred.  A-reg is cleared just before exit now.** May 6, 1988	     v1.3d4     Harry Yee** In the call GetScrapSize if there was an invalid scrap* opened from LoadTheScrap (i.e. an error occurred trying* to read it) the clipboard file was left opened, which* caused problems for some ProDOS calls which lock down* the disk if files are left open and then you move this* disk to another driver before making the ProDOS call.* I now close make sure the clipboard file is closed.** June 2, 1988	     v1.3d5     Harry Yee** Set the no special memory attribute bit for the memory* I allocated at bootinit.** June 30, 1988	     v1.4d1     Harry Yee** Version 1.4 to be included on System Disk 4.0:* In ScrapBootInit WAP was being set to the ptr of locked* down handle (MemPtr) instead of to the unlocked handle* itself (MemHandle).* Now the memory that is obtained during Bootinit is* locked when its used and unlocked otherwise.* Also ScrapReset has been completely rewritten to just* dispose of all memory allocated by the Scrap Manager* and then its WAP is set to zero. ScrapReset used to* dispose of the previous scrap (i.e. clipboard file)* which it no longer does.* InitScrapInfo has been done away with and incorporated* into ScrapBootInit.** August 9, 1988	 v1.4d2 (for System Disk 4.0d16) HY** ScrapBootInit was not checking if WAP was non-zero* before allocating memory for itself. Problem occurrs if* ones does a LoadOneTool and Scrap Mgr already loaded.* Two additional handles are created each time* ScrapBootInit is called. Bug can be verified by just* going into BASIC and then quitting.	We now check WAP* if non-zero we re-initialize the scrap path and then* get the hell out of there.*** 12 Aug 88	Steven Glass** The UnloadScrap called WriteOutScrap which was pushing * the wrong pointer to the file ref num and leaving * the file open.** Subsequent calls to read the scrap would fail because* of file aready open.** 19 Apr 89	Yee** Changed version number from 1.4 to 3.0.******************************************************************* BEGIN 6.0** 18-Sep-90	Dave Lyons** Removed dependency on all.macros.* Adding new call GetIndScrap.  Version is now $8301.* Simplified stack cleanup on the housekeeping calls.* Changed common.asm to use the ToStrip and ToBusyStrip vectors.* (Changed some JMLs to BRLs since they were in the same segment* anyway.)** 24-Sep-90	Dave Lyons** Known bug:  WriteOutThisOne is fried for >64K scraps.* Finished GetIndScrap.** 18-Nov-90	Dave Lyons** Fix WriteOutThisOne to work for >64K.  Reading scraps had* no problem, but it was inefficient.  Optimized RAM version* but did not patch it out for ROM 3.** TS3 patches out UnloadScrap and sucks in some subroutines.* UnloadScrap is the only call that winds up calling WriteOutThisOne,* so that's the only call we have to patch.** Changed clipboard filetype to from $00 to $F9.  Put back all.macros.** 14-Jan-91	Dave Lyons** Added a check for refnum=0 at LoadTheScrap ERROR.  At the* beginning of LoadTheScrap I zero out the refnum (at* [<MemPtr],#CloseParams).** 3-Apr-91	Dave Lyons** Fixed comment in GetIndScrap header--buffer format was wrong.** 5-Feb-92	Dave Lyons** Version $0301.******************************************************************* BEGIN 6.0.1** 17..18-Aug-92	Dave Lyons** Version $8302.  Cleaned out boring comments from 6.0.* New call ShowClipboard (not ROMmable).** 19-Aug-92	Dave Lyons** Fiddled with ShowClipboard a lot.** 1-Sep-92	Dave Lyons** PutScrap now bumps the scrap count.** 4..8-Sep-92	Dave Lyons** Fixed up ShowClipboard.  Optimized a lot of space-for-result* pushes to pha/pha instead of pushlong #0.** 14-Sep-92	Dave Lyons** When closing the clipboard window, zero NewDataWidth and* NewDataHeight so we re-set the window's data size the next* time we open.** 1-Apr-93	Steve Stephenson** Version $0302 for 6.0.1 (final)*********************************************************************************************************************************DebugSymbols	equ 0	include 'All.Macros'	include 'Special.Macros'	include 'E16.Window'	include 'E16.Locator'*****************************************************************			   **           Copyright Apple Computer, Inc. 1985-92	   **	All Rights Reserved		   **			   *****************************************************************;------------------------------------------;;   Global Equates;;------------------------------------------DebugVersion	equ 0TRUE	equ $FFFFFALSE	equ $0ScrapUserID	equ $4201	; special ID used so scrap memory will		; not get its purge level set to 3 by loaderToolNum	equ 22;----------------------------------------------------;; Zero page equates.;ScrapTablePtr	equ 1	; offset 1 because the old data bank is	stored at 0 OffsetToThisOne	equ ScrapTablePtr+4PtrToThisOne	equ OffsetToThisOne+4DestHandle	equ PtrToThisOne+4DestPtr	equ DestHandle+4WAPEntry	equ DestPtr+4MemHandle	equ WAPEntry+4MemPtr	equ MemHandle+4OrigDirect	equ MemPtr+4StdZPSize	equ OrigDirect-1******************************************************************************** Scrap Type constants** References:*   Apple IIgs Toolbox Reference Volume 1*   Apple IIgs Technical Note #99, Supplemental Scrap Types*******************************************************************************textScrap	equ $0000	;textpicScrap	equ $0001	;QuickDraw II picturesoundScrap	equ $0002	;sound in rSoundSample formatteStyleScrap	equ $0064	;Text Edit style information for texticonScrap	equ $4945	;icon with name/owner informationmaskScrap	equ $8001	;QuickDraw II picture to be used as a maskcolorScrap	equ $8002	;GS color tables (32 bytes each); need more HCGS scrap types??;----------------------------------------------------;; Scrap Record;o_ScrapType	equ 0o_ScrapSize	equ 2o_ScrapHandle	equ 6ScrapRecSize	equ 10;----------------------------------------------------;; ScrapAttributes for the memory I getScrapAttributes	equ $0008	; not special memory;----------------------------------------------------;; File type for clipboard file.;ClipFileType	equ $f9	;changed from 0 to $f9 19-Nov-90 DAL*ClipAuxType	equ 0;-----------------------------------------------------------;; Error Codes we need to label.;FileNotFound	equ $46	; ProDOS errorNotImpError	equ $16FFTypeError	equ $1610;-----------------------------------------------------------;; Equates for OS entry points.;OS_ENTRY	equ $E100A8OS_ENTRY2	equ $E100B0OS_Zero	equ $E100BAOS_Kind	equ $E100BCOS_Boot	equ $E100BD;-----------------------------------------------------------;; Memory Manager attributes;Attr_Locked	equ $8000	; 1 = LockedAttr_Fixed	equ $4000	; 1 = Not movableAttr_Purge	equ $0300	; 0 = No purge 1-3 purge levelAttr_NoCross	equ $0010	; 1 = May not cross	banksAttr_NoSpec	equ $0008	; 1 = May not use special memoryAttr_Page	equ $0004	; 1 = Page AlignedAttr_Addr	equ $0002	; 1 = Fixed addressAttr_Bank	equ $0001	; 1 = Fixed address;-----------------------------------------------;;   Equates for Stack based ProDOS calls;   and other memory locations that needed space;   because code is	being made non-self	modifying;CreateCall	equ $01DestroyCall	equ $02GetFileInfo	equ $06OpenCall	equ $10ReadCall	equ $12WriteCall	equ $13CloseCall	equ $14StackProDOS	equ $E100B0;Open Call Parameters:OpenParams	equ 0OpenID	equ 0	; reference number assigned to file by the OPEN callOpenPath	equ OpenID+2	; pointer to pathname of file to openOpenBuf	equ OpenPath+4	; pointer to I/O buffer;Read Call Parameters:ReadParams	equ 0ReadID	equ 0	; reference number assigned to file by the OPEN callReadTo	equ ReadID+2	; pointer to location of buffer where data is read intoReadAmount	equ ReadTo+4	; the number of bytes to be transferred;Write Call Parameters:WriteParams	equ 0WriteID	equ 0	; reference number assigned to file by the OPEN callWriteFrom	equ WriteID+2	; pointer to location of where data is to be written toWriteAmount	equ WriteFrom+4	; number of bytes to write;Close Call Parameters:CloseParams	equ 0CloseRef	equ 0	; reference number assigned to file by the OPEN call;Create Call Parameters:CreateParams	equ ReadAmount+8CreatePath	equ ReadAmount+8	; pointer to pathname of file to createCreateAccess	equ CreatePath+4	; word value, how file may be accessedCreateFileType	equ CreateAccess+2	; file type of fileCreateAuxType	equ CreateFileType+2 ; file's auxiliary typeCreateStType	equ CreateAuxType+4	; logical organization of fileCreateDate	equ CreateStType+2	; date which file was createdCreateTime	equ CreateDate+2	; time at which file was created;Destroy Call Parameters:DestroyParams	equ CreateTime+2DestroyPath	equ CreateTime+2HowMuchToWrite	equ DestroyParams+4HowMuchToRead	equ HowMuchToWrite+4NumEntries	equ HowMuchToRead+4	; used when reading	the clipboard file from diskFirstScrapHandle	equ NumEntries+2ScrapState	equ FirstScrapHandle+4 ; ScrapState indicates whether scrap	is currently in memory or on diskScrapCount	equ ScrapState+2	; ScrapCount is incremented each time zero scrap is calledScrapHandle	equ ScrapCount+2ScrapName	equ ScrapHandle+4	; Pointer to pathname of clipboard file.FIParams	equ ScrapName+4TotalMem	equ FIParams+29;-----------------------------------------------; ;  System Equates;IncBusyFlg	equ $E10064DecBusyFlg	equ $E10068;-----------------------------------------------;;           Imported address;;-----------------------------------------------	IMPORT OERROUT	IMPORT OENDCALL	IMPORT BUSYERR;-----------------------------------------------;;           Forward	address and entries;;-----------------------------------------------	entry ExitNoError	;18-Sep-90 DAL	entry GetIndScrap	;18-Sep-90 DAL	entry ShowClipboard	;17-Aug-92 DAL	ENTRY ScrapPath	ENTRY GetScrapState	ENTRY GetScrapCount	ENTRY SetScrapPath	ENTRY GetScrapPath	ENTRY GetScrapSize	ENTRY GetScrapHandle	ENTRY GetScrap	ENTRY PutScrap	ENTRY ZeroScrap	ENTRY LoadScrap	ENTRY UnloadScrap	ENTRY NotImp	ENTRY ScrapStatus	ENTRY ScrapReset	ENTRY ScrapVersion	ENTRY ScrapBootInit	ENTRY StartScrapCall	ENTRY EndScrapCall	ENTRY DisposeAllScraps	ENTRY DerefFirstHandle	ENTRY UnlockFirstHandle	ENTRY WriteOutThisOne	ENTRY WriteOutScrap	ENTRY EndScrapCall	ENTRY LoadTheScrap	ENTRY DeleteClipboard	ENTRY FindThisType	ENTRY DerefDest	ENTRY ReadInThisOne	ENTRY UnlockDest****************************************************************** ScrapCallTable*****************************************************************	EXPORT ScrapCallTableScrapCallTable	PROCTheBeginning	DC.L (TheEnd-TheBeginning)/4 	; call count + 1	DC.L ScrapBootInit-1 	; 0116	DC.L ExitNoError-1	 	; 0216 ScrapStartUp	DC.L ExitNoError-1 		; 0316 ScrapShutDown	DC.L ScrapVersion-1		; 0416 version call	DC.L ScrapReset-1		; 0516 reset call	DC.L ScrapStatus-1		; 0616 status call	DC.L NotImp-1		; 0716	DC.L NotImp-1		; 0816	DC.L UnloadScrap-1		; 0916	DC.L LoadScrap-1		; 0A16	DC.L ZeroScrap-1		; 0B16	DC.L PutScrap-1		; 0C16	DC.L GetScrap-1		; 0D16	DC.L GetScrapHandle-1 	; 0E16	DC.L GetScrapSize-1		; 0F16	DC.L GetScrapPath-1		; 1016	DC.L SetScrapPath-1		; 1116	DC.L GetScrapCount-1 	; 1216	DC.L GetScrapState-1 	; 1316*** new for 6.0	DC.L GetIndScrap-1		; 1416  (18-Sep-90 DAL)*** new for 6.0.1	DC.L ShowClipboard-1	; 1516  (17-Aug-92 DAL)TheEnd	ENDP****************************************************************** ScrapBootInit	(No inputs)** Modification History** 10 Apr 87    SEG**    Was not decrementing busy flag on way out.** 30 Jun 88    Harry Yee* 	InitScrapInfo has been incorporated into this *	routine.*****************************************************************	ENTRY ScrapBootInitScrapBootInit	PROCTheMemPtr	equ 1TheFirstScrapPtr	equ TheMemPtr+4TheFirstScrapHandle	equ TheFirstScrapPtr+4TheMemHandle	equ TheFirstScrapHandle+4OrigB	equ TheMemHandle+4OrigD	equ OrigB+1		jsl IncBusyFlg	phd	; save direct page register	phb	phk	; set data bank register	plb		cpy #0	beq NotInited	phy	; push MemHandle on stack	pha	pha	; space for FirstScrapHandle	pha	pha	; space for FirstScrapPtr	pha	pha	; space for MemPtr	pha	tsc	tcd	; turn stack into our zero page		lda [TheMemHandle]	; deref TheMemHandle	sta TheMemPtr	ldy #2	lda [TheMemHandle],y	sta TheMemPtr+2		lda #ScrapPath	; reset the name to	be used	ldy #ScrapName	; in case it was changed.	sta [TheMemPtr],y	lda #^ScrapPath	iny	iny	sta [TheMemPtr],y	brl GoHomeNotInited	pha	pha	; memory to be used for ProDOS calls and other junk		PushLong #TotalMem	PushWord #ScrapUserID	PushWord #Attr_Locked+Attr_NoSpec	pha	pha	_NewHandle	bcc NoError1	brl Error1NoError1	pha	pha	PushLong #2	PushWord #ScrapUserID	PushWord #Attr_NoSpec	pha	pha	_NewHandle	bcc NoError2	brl Error2NoError2	pha	; space for TheFirstScrapPtr	pha	pha	; space for TheMemPtr	pha	tsc	; switch in stack to be out zero page	tcd	lda [TheMemHandle]	; deref TheMemHandle	sta TheMemPtr	ldy #2	lda [TheMemHandle],y	sta TheMemPtr+2			lda [TheFirstScrapHandle] ; deref FirstScrapHandle	sta TheFirstScrapPtr	lda [TheFirstScrapHandle],y	sta TheFirstScrapPtr+2		lda TheFirstScrapHandle ; save TheFirstScrapHandle	ldy #FirstScrapHandle	sta [TheMemPtr],y	iny	iny	lda TheFirstScrapHandle+2	sta [TheMemPtr],y	lda #ScrapPath	; reset the name to	be used	ldy #ScrapName	; in case it was changed.	sta [TheMemPtr],y	lda #^ScrapPath	iny	iny	sta [TheMemPtr],y	lda #0	sta [TheFirstScrapPtr];----------------------------------------------------;; Now we look for the scrap.  We start by assuming; that the scrap is	on disk;	lda #0	ldy #ScrapState	sta [TheMemPtr],y	;----------------------------------------------------;; Look for clipboard file;; Now, if OS is active, we should look for the; clipboard file, otherwise assume the clipboard; is in memory.;	lda >OS_ENTRY	; for the os to be active, this must be	and #$00FF	; 5C, for JML op opcode.	cmp #$005C	bne NotActive	lda >OS_ENTRY2	; for the os to be active, this must be	and #$00FF	; 5C, for JML op opcode.	cmp #$005C	bne NotActive	lda >OS_Zero	; for os to be active, this must be zero	bne NotActive	lda >OS_Kind	; for os to be active, this must be one	and #$0001	beq NotActive	lda >OS_Boot	; for os to be active, this must be one	and #$0001	beq NotActive	lda #ScrapPath	; setup the parameters in memory 	ldy #FIParams	; for the ProDOS GetFileInfo call.	sta [TheMemPtr],y	lda #^ScrapPath	iny	iny	sta [TheMemPtr],y	lda TheMemPtr	clc	adc #FIParams	tax	lda TheMemPtr+2	adc #0	pha	phx	pea GetFileInfo	; check if the file */system/clipboard is there	jsl StackProDOS	bcc ScrapIsOnDiskNotActive	lda #1	ldy #ScrapState	sta [TheMemPtr],yScrapIsOnDisk	lda #0	ldy #ScrapCount	sta [TheMemPtr],yGoHome	PushWord #0	PushWord #ToolNum	; tool022	PushLong TheMemHandle	_SetWAP		ldy #4	; unlock TheMemHandle	lda [TheMemHandle],y;;;	and #$7FFF	asl a	lsr a	sta [TheMemHandle],y	pla	; get rid of TheMemPtr	pla	pla	; get rid of TheFirstScrapPtr	pla	pla	; get rid of TheFirstScrapHandle	pla	pla	; get rid of TheMemHandle	plaOut	plb	; restore original data bank 	ldy #0	brl BusyErr	; OrigD left on stack for BusyErr to restoreError2	plx	; get rid of TheFirstScrapHandle	plxError1	plx	; get rid of TheMemHandle	plx	tax	; put error in x-reg	bra Out	ENDP****************************************************************** ScrapVersion*****************************************************************	ENTRY ScrapVersionScrapVersion	PROC exportScrapVersionNumber	equ $0302	;1-Apr-93 SS	lda #ScrapVersionNumber	export ReturnOneWordReturnOneWord	sta 7,s	export ExitNoErrorExitNoError	lda #0	clc	rtl	ENDP****************************************************************** ScrapReset** Modification History** 10 Apr 87    SEG**    Was not decrementing busy flag on way out.** 29 Apr 88    HY**    A-Reg contained a non-zero value when it exited whether or not*    an error occurred. Therefore ScrapReset would always fail.    ** 08 Jun 88    HY**    ScrapReset now just disposes of all the memory allocated by*    the Scrap Manager and sets the WAP to zero.** 19 Sep 88	SEG**    The setWAP call had the wrong inputs.*    In addition, after a reset, the ScrapMgr has no memeory*    so we need to call the boot init call again to make things*    Kosher.*****************************************************************	ENTRY ScrapResetScrapReset	PROC	PushWord #ScrapUserID	_DisposeAll	; get rid of all memory allocated		; to the scrap manager	ldx #0	phx	; system tool set	PushWord #ToolNum	phx	phx	; set the wap to zero	_SetWAP	brl ScrapBootInit	ENDP****************************************************************** ScrapStatus** Returns true all the time since if we	are loaded, we are* active.*****************************************************************	ENTRY ScrapStatusScrapStatus	PROC	import ReturnOneWord	lda #True	bra ReturnOneWord	ENDP****************************************************************** NotImp** Error return for calls 7 and 8*****************************************************************	ENTRY NotImpNotImp	PROC	lda #NotImpError	sec	rtl	ENDP****************************************************************** ScrapDATA** The data structures for the ScrapManager are as follows.** Below we keep a handle called FirstScraphandle.  This is a* reference to a scrap table.  In the scrap table are* a series of scrap	records.  There is one record for each scrap* type represented in the table.** Each ScrapRecord in the ScrapTable contains the following* information:**        ScrapType*        ScrapSize*        ScrapHandle*******************************************************************	ENTRY ScrapDataScrapData	PROC;----------------------------------------------------;; Scrap data structure;; NumTypes in Scrap	 integer;     ScrapType1;     SizeofScrap1;     HandleToScrap1;;     ScrapType2;     SizeOfScrap2;     HandleToScrap2;;     ...;;     ScrapTypeN;     SizeOfScrapN;     HandleToScrapN;;----------------------------------------------------;; The scrap path is	the default clipboard path name; The file name is CLIPBOARD in the SYSTEM subdirectory; of the boot volume.;	ENTRY ScrapPathScrapPath	str '*/System/Clipboard'	ENDP****************************************************************** UnloadScrap**      No parameters.** Writes the scrap from memory to disk.*****************************************************************	ENTRY UnloadScrapUnloadScrap	PROC export	phy	pha	jsr StartScrapCall	ldy #ScrapState	lda [<MemPtr],y	beq AlreadyOnDisk	jsr WriteOutScrapAlreadyOnDisk	tax	jsr EndScrapCall	ldy #0	brl BusyErr	ENDP****************************************************************** LoadScrap**      No parameters.** Reads the scrap from disk to memory.	The contents are put* into the ScrapHandle.  The file CLIPBOARD is deleted after* it is read.*****************************************************************	ENTRY LoadScrapLoadScrap	PROC	phy	; save the WAPEntry 	pha	jsr StartScrapCall	ldy #ScrapState	lda [<MemPtr],y	beq YesOnDisk	lda #0	bra AlreadyInMemYesOnDisk	jsr LoadTheScrap	bcc AlreadyInMem	; no error occured	cmp #FileNotFound	beq IgnoreErrorAlreadyInMem	tax	jsr EndScrapCall	ldy #0	brl BusyErrIgnoreError	lda #0	bra AlreadyInMem	ENDP****************************************************************** ZeroScrap**      No parameters.** If the scrap exists, it is cleared out.  This means that it* disposes the scrap handle if there is	one or deletes the* CLIPBOARD file if	it exists.** The scrapCount field of the ScrapInfo	record is bumped.*****************************************************************	ENTRY ZeroScrapZeroScrap	PROC	phy	; save the WAPEntry	pha	jsr StartScrapCall	ldy #ScrapState	lda [<MemPtr],y	; if scrapstate is 0 then scrap is	beq ItsOnDisk	; on disk	jsr DisposeAllScraps	bcs ERRORFinish	ldy #ScrapCount	lda [<MemPtr],y	inc a	sta [<MemPtr],y	ldx #0GetOut	jsr EndScrapCall	ldy #0	brl BusyErrItsOnDisk	jsr DeleteClipboard	lda #1	ldy #ScrapState	sta [<MemPtr],y	bra FinishERROR	tax	bra GetOut	ENDP****************************************************************** PutScrap**       Length	: long int*       type	: integer*       SourcePtr	: POINTER** Appends user data	into the scrap.*****************************************************************	ENTRY PutScrapPutScrap	PROCRTL1	equ OrigDirect+2+4	; extra 4 is for the WAPEntry pushed on	stackRTL2	equ RTL1+3UserSrcPtr	equ RTL2+3UserSrcType	equ UserSrcPtr+4UserSrcLength	equ UserSrcType+2	phy	pha	jsr StartScrapCall*** added 1-Sep-92 DAL -- PutScrap now bumps the scrap count	ldy #ScrapCount	lda [<MemPtr],y	inc a	sta [<MemPtr],y*** end 1-Sep-92	ldy #ScrapState	lda [<MemPtr],y	bne AlreadyInMem;----------------------------------------------------;; We really don't care if the load fails since; it is like loading a empty scrap which we already; have.	jsr LoadTheScrapAlreadyInMem	jsr DerefFirstHandle	lda UserSrcType	jsr FindThisType	bcs AddThisType	jmp FoundType;----------------------------------------------------;; The type is not in the data so I must	add it by; making the scrap table bigger.;AddThisType	jsr UnlockFirstHandle	pha	pha	ldy #FirstScrapHandle+2	lda [<MemPtr],y	pha	dey	dey	lda [<MemPtr],y	pha	_GetHandleSize	lda 1,s	; save a copy of the size of this	sta <OffsetToThisOne ; thing for use later	lda 3,s	sta <OffsetToThisOne+2	lda 1,s	; now add the size of one more	clc	; record to this and do a	adc #ScrapRecSize	; set handle size.	sta 1,s	bcc NoCarry	lda 3,s	inc a	sta 3,sNoCarry	ldy #FirstScrapHandle+2	lda [<MemPtr],y	pha	dey	dey	lda [<MemPtr],y	pha	_SetHandleSize	bcc SizeAdjusted	jmp ERRORSizeAdjusted	jsr DerefFirstHandle ; deref again	lda [<ScrapTablePtr] ; bump count of num types in scrap	inc a	sta [<ScrapTablePtr]	lda <ScrapTablePtr	; now compute the pointer to	clc	; the ScrapRec we just made	adc <OffsetToThisOne	sta <PtrToThisOne	lda <ScrapTablePtr+2	adc <OffsetToThisOne+2	sta <PtrToThisOne+2	lda UserSrcType	; put SrcType in recrod	sta [<PtrToThisOne]	ldy #o_ScrapSize	; set size of handle to zero	lda #0	sta [<PtrToThisOne],y	iny	iny	sta [<PtrToThisOne],y;----------------------------------------------------;; Get a handle of zero size;	pha	pha	; space for handle	lda #0	pha	pha	; size 0	PushWord #ScrapUserID	PushWord #ScrapAttributes	pha	pha	; no loc info	_Newhandle	bcc GotNewHandle	brl ERRORGotNewHandle	ldy #o_ScrapHandle	pla	sta [<PtrToThisOne],y	iny	iny	pla	sta [<PtrToThisOne],y;----------------------------------------------------;; Type is already in the scrap data so I just need; to append the passed data onto it.;FoundType	lda <ScrapTablePtr	; set or reset PtrToThisOne	clc	; based on OffsetToThisOne	adc <OffsetToThisOne	sta <PtrToThisOne	lda <ScrapTablePtr+2	adc <OffsetToThisOne+2	sta <PtrToThisOne+2	ldy #o_ScrapSize	; calculate new handle size	lda [<PtrToThisOne],y ; by adding old size to	clc	; SrcLength	adc UserSrcLength	tax	iny	iny	lda [<PtrToThisOne],y	adc UserSrcLength+2	pha	; push size on stack	phx	ldy #o_ScrapHandle+2 ; now get handle from scrap record	lda [<PtrToThisOne],y ; push it and do set handle size	pha	dey	dey	lda [<PtrToThisOne],y	pha	_SetHandleSize	bcs ERROR	; DAN H. (so will report errors)	ldy #o_ScrapHandle	; get handle again from scrap record	lda [<PtrToThisOne],y ; put in dest handle	sta <DestHandle	; and deref it.	iny	iny	lda [<PtrToThisOne],y	sta <DestHandle+2	jsr DerefDest	lda <DestPtr	; figure out where in dest to	ldy #o_ScrapSize	; start adding by adding orig	adc [<PtrToThisOne],y ; size to DestPtr.	sta <DestPtr	lda <DestPtr+2	iny	iny	adc [<PtrToThisOne],y	sta <DestPtr+2;----------------------------------------------------;; Now move it;	PushLong UserSrcPtr	PushLong <DestPtr	PushLong UserSrcLength	_BlockMove	jsr UnlockDest;----------------------------------------------------;; Finally, set the scrap size field in the record to; the new handle size.	clc	ldy #o_ScrapSize	; and put result size in	lda [<PtrToThisOne],y ; scrap record.	adc UserSrcLength	sta [<PtrToThisOne],y	iny	iny	lda [<PtrToThisOne],y	adc UserSrcLength+2	sta [<PtrToThisOne],y;----------------------------------------------------;; Now unlock First handle;	jsr UnlockFirstHandle	ldx #0	; for no errorGetOut	jsr EndScrapCall	ldy #10	brl BusyErrERROR	tax	bra GetOut	ENDP****************************************************************** GetScrap**        UserHandle		(pushed top to bottom)*        UserType** Copies the scrap to user memory.*****************************************************************	ENTRY GetScrapGetScrap	PROCRTL1	equ OrigDirect+2+4RTL2	equ RTL1+3UserType	equ RTL2+3UserHandle	equ UserType+2	phy	; save WAPEntry	pha	jsr StartScrapCall	ldy #ScrapState	lda [<MemPtr],y	bne AlreadyInMem;----------------------------------------------------;; We really don't care if the load fails since; it is like loading a empty scrap which we already; have.;	jsr LoadTheScrapAlreadyInMem	jsr DerefFirstHandle	lda UserType	jsr FindThisType	bcc FoundType	lda #TypeError	bra ERROR;----------------------------------------------------;; Type is already in the scrap data so I just need; to append the passed data onto it.;FoundType	lda <ScrapTablePtr	; set or reset PtrToThisOne	clc	; based on OffsetToThisOne	adc <OffsetToThisOne	sta <PtrToThisOne	lda <OffsetToThisOne+2	adc <ScrapTablePtr+2	sta <PtrToThisOne+2	ldy #o_ScrapSize+2	; get size handle will be	lda [<PtrToThisOne],y ; and set user handle to this	pha	; size	dey	dey	lda [<PtrToThisOne],y	pha	PushLong UserHandle	_SetHandleSize	bcs ERROR	ldy #o_ScrapHandle+2 ; now use handle to handle to make	lda [<PtrToThisOne],y ; copy.	pha	dey	dey	lda [<PtrToThisOne],y	pha	PushLong UserHandle	ldy #o_ScrapSize+2	lda [<PtrToThisOne],y	pha	dey	dey	lda [<PtrToThisOne],y	pha	_HandToHand	jsr UnlockFirstHandle	ldx #0	; for no errorGetOut	jsr EndScrapCall	ldy #6	brl BusyErrERROR	tax	bra GetOut	ENDP****************************************************************** GetScrapHandle**              Space For Handle*              ScrapType** Returns the handle to the scrap of the specified type.  We* provide this so that the user does not have to make a copy of* what is in the scrap to "Get" it.*****************************************************************	ENTRY GetScrapHandleGetScrapHandle	PROCRTL1	equ OrigDirect+2+4RTL2	equ RTL1+3UserType	equ RTL2+3UserHandle	equ UserType+2	phy	pha	jsr StartScrapCall	ldy #ScrapState	lda [<MemPtr],y	bne AlreadyInMem;----------------------------------------------------;; We really don't care if the load fails since; it is like loading a empty scrap which we already; have.;	jsr LoadTheScrapAlreadyInMem	jsr DerefFirstHandle	lda UserType	jsr FindThisType	bcc FoundType	lda #TypeError	bra ERRORFoundType	lda <ScrapTablePtr	; set or reset PtrToThisOne	clc	; based on OffsetToThisOne	adc <OffsetToThisOne	sta <PtrToThisOne	lda <OffsetToThisOne+2	adc <ScrapTablePtr+2	sta <PtrToThisOne+2	ldy #o_ScrapHandle	; get handle	lda [<PtrToThisOne],y	sta UserHandle	iny	iny	lda [<PtrToThisOne],y	sta UserHandle+2	ldx #0	; for no errorGetOut	phx	jsr UnlockFirstHandle	plx	jsr EndScrapCall	ldy #2	brl BusyErrERROR	tax	bra GetOut	ENDP****************************************************************** GetScrapSize**              Space For Size*              ScrapType** Returns the size of the scrap of the specified type.*****************************************************************	ENTRY GetScrapSizeGetScrapSize	PROCRTL1	equ OrigDirect+2+4RTL2	equ RTL1+3UserType	equ RTL2+3UserSize	equ UserType+2	phy	pha	jsr StartScrapCall	ldy #ScrapState	lda [<MemPtr],y	bne AlreadyInMem;----------------------------------------------------;; We really don't care if the load fails since; it is like loading a empty scrap which we already; have.;	jsr LoadTheScrapAlreadyInMem	jsr DerefFirstHandle	lda UserType	jsr FindThisType	bcc FoundType	lda #TypeError	bra ERRORFoundType	lda <ScrapTablePtr	; set or reset PtrToThisOne	clc	; based on OffsetToThisOne	adc <OffsetToThisOne	sta <PtrToThisOne	lda <OffsetToThisOne+2	adc <ScrapTablePtr+2	sta <PtrToThisOne+2	ldy #o_ScrapSize	; get size	lda [<PtrToThisOne],y	sta UserSize	iny	iny	lda [<PtrToThisOne],y	sta UserSize+2	ldx #0	; for no errorGetOut	phx	jsr UnlockFirstHandle	plx	jsr EndScrapCall	ldy #2	brl BusyErrERROR	tax	bra GetOut	ENDP****************************************************************** GetScrapPath**              No inputs** Returns a pointer	to the path name string used by the* clipboard.*****************************************************************	ENTRY GetScrapPathGetScrapPath	PROCOrigD	equ 1WAPPointer	equ OrigD+2RTL1	equ WAPPointer+4RTL2	equ RTL1+3PathPtr	equ RTL2+3	phy	; save WAPEntry	pha	phd	; save direct page	tsc	tcd	; make stack the direct page	ldy #2	; dereference WAPEntry	lda [<WAPPointer],y	tax	lda [<WAPPointer]	sta <WAPPointer	txa 	sta <WAPPointer+2	ldy #ScrapName	lda [<WAPPointer],y	sta <PathPtr	iny	iny	lda [<WAPPointer],y	sta <PathPtr+2	pld	; restore original direct page	pla	; get rid of WAPPointer	pla	brl ExitNoError	ENDP****************************************************************** SetScrapPath**              Ptr to New Path** Sets the pointer to the path name string used by the* clipboard.*****************************************************************	ENTRY SetScrapPathSetScrapPath	PROCOrigD	equ 1WAPPointer	equ OrigD+2RTL1	equ WAPPointer+4RTL2	equ RTL1+3PathPtr	equ RTL2+3	phy	; save WAPEntry	pha	phd	; save direct page	tsc	tcd	; make stack the direct page	ldy #2	; dereference WAPEntry	lda [<WAPPointer],y	tax	lda [<WAPPointer]	sta <WAPPointer	txa 	sta <WAPPointer+2	lda <PathPtr	ldy #ScrapName	sta [<WAPPointer],y	lda <PathPtr+2	iny	iny	sta [<WAPPointer],y	pld	; restore original direct page	pla	; get rid of WAPPointer off stack	pla	ldy #4	brl oendcall	ENDP****************************************************************** GetScrapCount**              Space for count** Returns the global variable scrap count*****************************************************************	ENTRY GetScrapCountGetScrapCount	PROCOrigD	equ 1WAPPointer	equ OrigD+2RTL1	equ WAPPointer+4RTL2	equ RTL1+3Result	equ RTL2+3	phy	; save WAPEntry	pha	phd	; save direct page	tsc	tcd	; make stack the direct page	ldy #2	; dereference WAPEntry	lda [<WAPPointer],y	tax	lda [<WAPPointer]	sta <WAPPointer	txa 	sta <WAPPointer+2	ldy #ScrapCount	lda [<WAPPointer],y	sta <Result	pld	; restore original direct page	pla	; get rid of WAPPointer on stack	pla	brl ExitNoError	ENDP****************************************************************** GetScrapState**              Space for count** Returns the global variable scrap count*****************************************************************	ENTRY GetScrapStateGetScrapState	PROCOrigD	equ 1WAPPointer	equ OrigD+2RTL1	equ WAPPointer+4RTL2	equ RTL1+3Result	equ RTL2+3	phy	; save WAPEntry	pha	phd	; save direct page	tsc	tcd	; make stack the direct page	ldy #2	; dereference WAPEntry	lda [<WAPPointer],y	tax	lda [<WAPPointer]	sta <WAPPointer	txa 	sta <WAPPointer+2	ldy #ScrapState	lda [<WAPPointer],y	sta <Result	pld	; restore original direct page	pla	; get rid of WAPPointer on stack	pla	brl ExitNoError	ENDP****************************************************************** GetIndScrap** New call for 6.0   18-Sep-90 DAL** Description:** GetIndScrap(index,bufferPtr)*              WORD      LONG** Bits 24-31 of bufferPtr are reserved and must currently be 0.** Fills the supplied 10-byte buffer with information on the* Index-th scrap. The format of the buffer is:**   +000 scrap type   (word)*   +002 scrap size   (long)*   +006 scrap handle (long)*****************************************************************GetIndScrap	PROC exportWAPPointer	equ OrigDirect+2RTL1	equ WAPPointer+4RTL2	equ RTL1+3BuffPtr	equ RTL2+3IndexParm	equ BuffPtr+4	phy	pha	jsr StartScrapCall	ldy #ScrapState	lda [<MemPtr],y	bne @AlreadyInMem	jsr LoadTheScrap@AlreadyInMem	jsr DerefFirstHandle	lda IndexParm	beq @notFound	dec a	cmp [<scrapTablePtr]	bcs @notFound	tay	lda #2	iny@loop	dey	beq @multiplied	clc	adc #ScrapRecSize	bra @loop@multiplied	tay	clc	tya	adc <scrapTablePtr	tay	lda <scrapTablePtr+2	adc #0	pha	phy	pei <BuffPtr+2	pei <BuffPtr	pea 0	pea ScrapRecSize	_BlockMove	lda #0	;no error	bra @exit@notFound	lda #typeError* error in A@exit	pha	;save error code	jsr UnlockFirstHandle	plx	jsr EndScrapCall	ldy #6	;strip 6 bytes of parameters	brl BusyErr	ENDP****************************************************************** ShowClipboard** New call for 6.0.1   17-Aug-92 DAL** Description:** ShowClipboard(flags,@rectangle):@Wind*                WORD   LONG       LONG** Opens a system window to display the clipboard.  Returns the* window pointer at the end of the call (nil = not open).** If flag bit 15 is set, open the window (or bring to front if* already open).** If flag bit 14 is set, close the window if it's open.******************************************************************* The content of the Clipboard window is customizable through* SendRequest.  The system sends systemSaysDoClipboard, request* $000C, as follows:** dataIn:*   +000 Word  actionCode (0=draw contents, 1=hit a control, 2=killing controls)*   +002 Long  Clipboard window pointer*   +006 Word  clipVertOffset (top of area to draw in)*   +008 Word  clipHorOffset (left edge of area to draw in)*   +010 Word  reasonableMaxWidth*   +012 Long  controlID of control hit (when actionCode = 1)** dataOut:*   Defined for action-code = draw only.**   +000 Word  recvCount*   +002 Word  dataHeight*   +004 Word  dataWidth*   +006 Long  clipKindPtr*****************************************************************ShowClipboard	proc export	phb	phk	plb	phd	tsc	tcdoNDAStructure	equ 24	;offset into auxWindInfo record@oldD	equ 1@oldB	equ @oldD+2@rtl	equ @oldB+1@rectPtr	equ @rtl+6@flags	equ @rectPtr+4@result	equ @flags+2	bit <@flags	bvc @dontClose	lda clipWindow+1	beq @dontClose	;not open!	jsr PushWindPtr	_CloseNDAByWinPtr@dontClose	lda <@flags	bmi @normalOpen	brl @dontOpen@normalOpen*** If the window already exists, just bring it to the front.	lda clipWindow+1	beq @noWindow	jsr PushWindPtr	_SelectWindow@toError	brl @error@noWindow	lda #20	;left edge in 640	jsr HalfIf320	sta clipWindRect+2	;left edge	lda #500-20	;width in 640	jsr HalfIf320	adc clipWindRect+2	sta clipWindRect+6	;right edge	pha	pha	;space for NewWindow2	ldx #0	;handy zero	phx	phx	;override title	phx	phx	;refcon	pushlong #UpdateClipWindow	phx	phx	;defproc	pea 0	;ref is pointer	pushlong #clipWindTemplate	pea $800E	;rWindParam1	_NewWindow2	plx	ply	bcs @toError	stx clipWindow	sty clipWindow+2	lda #^kindNull	sta clipKindPtr+2	lda #kindNull	sta clipKindPtr	pha	pha	_GetPort	jsr PushWindPtr	_SetSysWindow	jsr PushWindPtr	_SetPort	pea $0004	;use all 16 bits of text colors	_SetFontFlags	pea $fffe	jsr PushWindPtr	_SetOriginMask*** stuff a Desk Manager record pointer into the window's AuxWindInfo	pha	pha	jsr PushWindPtr	_GetAuxWindInfo	phd	tsc	tcd	ldy #oNDAStructure+2	lda #^TheNDAStructure	sta [3],y	dey	dey	lda #TheNDAStructure	sta [3],y	pld	pla	pla	jsr ShowMainWindow	jsr InitKindString	_SetPort	pushlong #clipRunQueue	_AddToRunQ@dontOpen@exit	lda #0	;error@error	ldx clipWindow+2	stx <@result+2	ldx clipWindow	stx <@result	pld	plb	tax	ldy #6	;strip 6 bytes	jml $e10184	;ToStripPushWindPtr	plx	pushlong clipWindow	phx	rts;; ShowMainWindow;; Input:  Port is already set to main window, which is invisible.;; Animate a zoom-out effect with WhooshRect, and then show the window.;ShowMainWindow	name	pushlong #bigRect	_GetPortRect	pushlong #bigRect	_LocalToGlobal	pushlong #bigRect+4	_LocalToGlobal	pea $8000	;zoom-out flag	pea 0	pushlong #smallRect	pushlong #bigRect	_WhooshRect	jsr PushWindPtr	_ShowWindow	rtssmallRect	dc.w 14,14,15,15	;tiny rectangle to zoom out frombigRect	dc.w 0,0,0,0	;window rectangleclipWindTemplate	dc.w templateEnd-clipWindTemplate	dc.w $DD90		;plFrame (frame bits)	dc.l clipTitle		;plTitle	dc.l $00000000		;plRefCon	dc.w 0,0,0,0		;plZoomRect	dc.l $07FF0001		;plColorTable (striped title)	dc.w 0,0		;plYOrigin, plXOrigin	dc.w 0,0		;plDataHeight, plDataWidth	dc.w 0,0		;plMaxHeight, plMaxWidth	dc.w 10,16		;plVerScroll, plHorScroll	dc.w 0,0		;plVerPage, plHorPage	dc.l 0		;plInfoText (info RefCon)	dc.w 11		;plInfoHeight	dc.l 0		;plDefProc	dc.l clipInfoDraw		;plInfoDraw	dc.l 0		;plContentDrawclipWindRect	dc.w 120,20,180,500		;plPosition	dc.l $FFFFFFFF		;plPlane	dc.l 0		;plControlList (no controls)	dc.w $0800		;plInDesctemplateEndclipTitle	str ' Clipboard 'TheNDAStructure	dc.w 0	;status--not open	dc.l 0	;open proc	dc.l ClipCloseProc	;close	dc.l ClipActionProc	;action	dc.l 0	;init	dc.w 0	;period (reserved)	dc.w $A146	;mask (smart+update+activate+buttonDown+buttonUp)	dc.l 0	;serviced (reserved)	d