r a	;17-Aug-92 DAL	sta [<MemHandle],y	ply	; save rts addr in y	plb	tsc	clc	adc #StdZPSize	tcs	lda 1,s	; save direct page	sta 5,s	; overwrite the high word of WAPEntry on stack	pla	; get rid of direct	page still on stack	                	pla	; get rid of low word of WAPEntry	phy	; put rts back on stack	rts	ENDP****************************************************************** Scrap Utility Routines*****************************************************************	ENTRY DerefFirstHandleDerefFirstHandle	PROC	ldy #FirstScrapHandle	lda [<MemPtr],y	sta <ScrapTablePtr	iny	iny	lda [<MemPtr],y	sta <ScrapTablePtr+2	ldy #4	lda [<ScrapTablePtr],y	ora #$8000	sta [<ScrapTablePtr],y	dey	dey	lda [<ScrapTablePtr],y	tax	lda [<ScrapTablePtr]	sta <ScrapTablePtr	stx <ScrapTablePtr+2	rts	ENDP	ENTRY UnlockFirstHandleUnlockFirstHandle	PROC	ldy #FirstScrapHandle	lda [<MemPtr],y	sta <ScrapTablePtr	iny	iny	lda [<MemPtr],y	sta <ScrapTablePtr+2	ldy #4	lda [<ScrapTablePtr],y	and #$7FFF	sta [<ScrapTablePtr],y	rts	ENDP	ENTRY DerefDestDerefDest	PROC	ldy #4	lda [<DestHandle],y	ora #$8000	sta [<DestHandle],y	dey	dey	lda [<DestHandle],y	sta <DestPtr+2	lda [<DestHandle]	sta <DestPtr	rts	ENDP	ENTRY UnlockDestUnlockDest	PROC	ldy #4	lda [<DestHandle],y	and #$7FFF	sta [<DestHandle],y	rts	ENDP****************************************************************** FindThisType** We search through	the scrap table for	a scrap record of* the type passed in the a register.** If we find it, we	return with the carry clear and the* variable OffsetToThisOne set on zero page.** If we do not find	it we return with carry set.*****************************************************************	ENTRY FindThisTypeFindThisType	PROC	pha	; store the type to	find on the stack	ldy #2	; y points to first	scrap record	ldx #1	; x is countKeepLooking		;	txa	; compare count to num scrap records	cmp [<ScrapTablePtr]	beq LastItem	bcs NotInTableLastItem	lda [<ScrapTablePtr],y ; get the type of this scrap record	cmp 1,s	; compare to value on stack	beq FoundIt	tya	; bump y by size of	record	clc	adc #ScrapRecSize	tay	inx	; bump count by 1	bra KeepLookingFoundIt	pla	; carry is clear here	sty <OffsetToThisOne	stz <OffsetToThisOne+2	clc	rtsNotInTable	pla	; carry is set here	rts	ENDP	eject****************************************************************** DisposeAllScraps** Traverses through	the scrap table disposing of all the* handles in each scrap record.** The ScrapTablePtr	must already be setup on zero page* when this is called.*****************************************************************	ENTRY DisposeAllScrapsDisposeAllScraps	PROC	jsr DerefFirstHandle	ldy #2+o_ScrapHandle ; y points to first scrap record	ldx #0	; x is count, DAN H. (to do last one)KeepLooking		;	txa	; compare count to num scrap records	cmp [<ScrapTablePtr]	bcs TableComplete	phx	; save x and y	phy	pea 0	pea 0	lda [<ScrapTablePtr],y ; get the type of this scrap record	sta 1,s	iny	iny	lda [<ScrapTablePtr],y	sta 3,s	_Disposehandle	bcs ERROR	ply	; get back x and y	plx	tya	; bump y by size of	record	clc	adc #ScrapRecSize	tay	inx	; bump count by 1	bra KeepLookingTableComplete	jsr UnlockFirstHandle	PushLong #2	ldy #FirstScrapHandle+2	lda [<MemPtr],y	pha	dey	dey	lda [<MemPtr],y	pha	_SetHandleSize	bcs ERROR2	jsr DerefFirstHandle	lda #0	sta [<ScrapTablePtr]	jsr UnlockFirstHandle	clc	rtsERROR	ply	plxERROR2	rts	ENDP	eject****************************************************************** DeleteClipboard** Deletes the clipboard file (if it exists).*****************************************************************	ENTRY DeleteClipBoardDeleteClipBoard	PROC	ldy #ScrapName	lda [<MemPtr],y	ldy #DestroyPath	sta [<MemPtr],y	ldy #ScrapName+2	lda [<MemPtr],y	ldy #DestroyPath+2	sta [<MemPtr],y	lda <MemPtr	clc	adc #DestroyParams	tax	lda <MemPtr+2	adc #0	pha	phx	pea DestroyCall	jsl StackProDOS	rts	ENDP	eject****************************************************************** LoadTheScrap** Loads the scrap from the clipboard file and creates the* appropriate scrap	table in memory.*** The scrap is read	into memory as follows:**      First, the ScrapTable is read from disk as is (this*      includes the	handles which are no longer valid but*      serve as place holders).**      Then each scrap is read out.*****************************************************************	ENTRY LoadTheScrapLoadTheScrap	PROC	ldy #CloseParams	lda #0	sta [<MemPtr],y;----------------------------------------------------;; Open the file and	copy the ID's;	ldy #ScrapName	lda [<MemPtr],y	ldy #OpenPath	sta [<MemPtr],y	ldy #ScrapName+2	lda [<MemPtr],y	ldy #OpenPath+2	sta [<MemPtr],y	lda <MemPtr	clc	adc #OpenParams	tax	lda <MemPtr+2	adc #0	pha	phx	pea OpenCall	jsl StackProDOS	bcc OpenOK	jmp ERROROpenOK;----------------------------------------------------;; Read in the number of entries in the scrap table;	lda <MemPtr	clc	adc #NumEntries	ldy #ReadTo	sta [<MemPtr],y	lda <MemPtr+2	adc #0	iny	iny	sta [<MemPtr],y	lda #2	ldy #ReadAmount	sta [<MemPtr],y	iny	iny	lda #0	sta [<MemPtr],y	lda <MemPtr	clc	adc #ReadParams	tax	lda <MemPtr+2	adc #0	pha	phx	pea ReadCall	jsl StackProDOS	bcc ReadOK	jmp ERRORReadOK;----------------------------------------------------;; Calculate the size of the scrap table	record.; and how much more	needs to be read.;	pha	pha	ldy #NumEntries	lda [<MemPtr],y	pha	PushWord #ScrapRecSize	_Multiply	lda 1,s	ldy #ReadAmount	sta [<MemPtr],y	clc	adc #2	sta 1,s	lda 3,s	iny	iny	sta [<MemPtr],y	bcc NoCarry	inc a	sta 3,sNoCarry	ldy #FirstScrapHandle+2	lda [<MemPtr],y	pha	dey	dey	lda [<MemPtr],y	pha	_SetHandleSize	bcc SizeOK	jmp ERRORSizeOK	jsr DerefFirstHandle	ldy #NumEntries	lda [<MemPtr],y	sta [<ScrapTablePtr]	lda <ScrapTablePtr	clc	adc #2	ldy #ReadTo	sta [<MemPtr],y	lda <ScrapTablePtr+2	bcc NoCarry2	inc aNoCarry2	iny	iny	sta [<MemPtr],y	lda <MemPtr	clc	adc #ReadParams	tax	lda <MemPtr+2	adc #0	pha	phx	pea ReadCall	jsl StackProDOS	bcs ERROR;----------------------------------------------------;; Now read in individual scraps.;	lda <ScrapTablePtr	clc	adc #2	sta <PtrToThisOne	lda <ScrapTablePtr+2	bcc NoCarry3	inc aNoCarry3	sta <PtrToThisOne+2	lda #0Loop	cmp [<ScrapTablePtr]	bcs AllDone	pha	jsr ReadInThisOne	bcs ERROR2	lda <PtrToThisOne	clc	adc #ScrapRecSize	sta <PtrToThisOne	lda <PtrToThisOne+2	bcc NoCarry4	inc aNoCarry4	sta <PtrToThisOne+2	pla	inc a	bra LoopAllDone;----------------------------------------------------;; Close it all down.;	lda <MemPtr	clc	adc #CloseParams	tax	lda <MemPtr+2	adc #0	pha	phx	pea CloseCall	jsl StackProDOS;----------------------------------------------------;; Set flag to indicate that clipboard is in memory;	lda #1	ldy #ScrapState	sta [<MemPtr],y;----------------------------------------------------;; Unlock the scrap table;	jsr UnlockFirstHandle;----------------------------------------------------;; Delete the file;	jsr DeleteClipboard	lda #0	clc	rtsERROR2	plxERROR	pha	; save error code	ldy #CloseParams	;14-Jan-91 DAL (added)	lda [<MemPtr],y	;14-Jan-91 DAL	beq @NeverCloseZero	;14-Jan-91 DAL	lda <MemPtr	; close the clipboard file just in case its	clc	; been left open. 	adc #CloseParams	; HY 5/6/88	tax	lda <MemPtr+2	adc #0	pha	phx	pea CloseCall	jsl StackProDOS@NeverCloseZero		;added 14-Jan-91 DAL	jsr UnlockFirstHandle	pla	; get back error code	sec	; signal error	rts	ENDP	eject****************************************************************** ReadInThisOne** Reads the scrap whose table entry is pointed to by* PtrToThisOne from	the open file.** If the amount to read is greater than	64K it is read in 64K* chunks since prodos cannot read more than that at once.** Returns any error	in a-reg.*****************************************************************	ENTRY ReadInThisOneReadInThisOne	PROC	pha	pha	ldy #o_ScrapSize+2	lda [<PtrToThisOne],y	pha	ldy #HowMuchToRead+2	sta [<MemPtr],y	ldy #o_ScrapSize	lda [PtrToThisOne],y	pha	ldy #HowMuchToRead	sta [<MemPtr],y	PushWord #ScrapUserID	PushWord #ScrapAttributes	pha	pha	_NewHandle	bcc NoError	plx	plx	rtsNoError	pla	sta <DestHandle	ldy #o_Scraphandle	sta [<PtrToThisOne],y	pla	sta <DestHandle+2	iny	iny	sta [<PtrToThisOne],y	jsr DerefDest	lda <DestPtr	ldy #ReadTo	sta [<MemPtr],y	lda <DestPtr+2	iny	iny	sta [<MemPtr],y	ldy #HowMuchToRead+2	;added 18-Nov-90 DAL	lda [<MemPtr],y		;added 18-Nov-90 DAL	ldy #ReadAmount+2		;added 18-Nov-90 DAL	sta [<MemPtr],y		;added 18-Nov-90 DAL	ldy #HowMuchToRead		;added 18-Nov-90 DAL	lda [<MemPtr],y		;added 18-Nov-90 DAL	ldy #ReadAmount		;added 18-Nov-90 DAL	sta [<MemPtr],y		;added 18-Nov-90 DAL	lda <MemPtr	clc	adc #ReadParams	tax	lda <MemPtr+2	adc #0	pha	phx	pea ReadCall	jsl StackProDOSError	php	pha	jsr UnlockDest	pla	plp	rts	ENDP	eject****************************************************************** WriteOutScrap** Writes the scrap in memory to disk.  Disposes of scrap in* memory.** The scrap in memory is written as follows:**      First, the ScrapTable is written	out as it is (this*      includes the	handles which won't be valid later but*      serve as place holders).**      Then each scrap is written out.*****************************************************************	ENTRY WriteOutScrapWriteOutScrap	PROC;----------------------------------------------------;; First delete anything that may be there.;	jsr DeleteClipboard;----------------------------------------------------;; Now create a new clipboard file;	ldy #ScrapName	lda [<MemPtr],y	ldy #CreatePath	sta [<MemPtr],y	ldy #ScrapName+2	lda [<MemPtr],y	ldy #CreatePath+2	sta [<MemPtr],y	lda #$C3	ldy #CreateAccess	sta [<MemPtr],y	lda #ClipFileType	ldy #CreateFileType	sta [<MemPtr],y	lda #0	ldy #CreateAuxType	sta [<MemPtr],y	iny	iny	sta [<MemPtr],y	lda #1	ldy #CreateStType	sta [<MemPtr],y	lda #0	ldy #CreateDate	sta [<MemPtr],y	ldy #CreateTime	sta [<MemPtr],y	lda <MemPtr	clc	adc #CreateParams	tax	lda <MemPtr+2	adc #0	pha	phx	pea CreateCall	jsl StackProDOS	bcc NoCreError	jmp ErrorNoCreError;----------------------------------------------------;; Open the file and	copy the IDs;	ldy #ScrapName	lda [<MemPtr],y	ldy #OpenPath	sta [<MemPtr],y	ldy #ScrapName+2	lda [<MemPtr],y	ldy #OpenPath+2	sta [<MemPtr],y	lda <MemPtr	clc	adc #OpenParams	tax	lda <MemPtr+2	adc #0	pha	phx	pea OpenCall	jsl StackProDOS	bcc NoOpenErr	jmp ERRORNoOpenErr;----------------------------------------------------;; Write out the scrap table	jsr DerefFirstHandle	lda <ScrapTablePtr	ldy #WriteFrom	sta [<MemPtr],y	iny	iny	lda <ScrapTablePtr+2	sta [<MemPtr],y	pha	pha	ldy #FirstScrapHandle+2	lda [<MemPtr],y	pha	dey	dey	lda [<MemPtr],y	pha	_GetHandleSize	bcs ERROR	pla	ldy #WriteAmount	sta [<MemPtr],y	pla	iny	iny	sta [<MemPtr],y	lda <MemPtr	clc	adc #WriteParams	tax	lda <MemPtr+2	adc #0	pha	phx	pea WriteCall	jsl StackProDOS	bcs ERROR;----------------------------------------------------;; Now write out individual scraps.;	lda <ScrapTablePtr	clc	adc #2	sta <PtrToThisOne	lda <ScrapTablePtr+2	bcc NoCarry	inc aNoCarry	sta <PtrToThisOne+2	lda #0Loop	cmp [<ScrapTablePtr]	bcs AllDone	pha	jsr WriteOutThisOne	bcs ERROR2	lda <PtrToThisOne	clc	adc #ScrapRecSize	sta <PtrToThisOne	lda <PtrToThisOne+2	bcc NoCarry2	inc aNoCarry2	sta <PtrToThisOne+2	pla	inc a	bra LoopAllDone;----------------------------------------------------;; Close it all down.;	lda <MemPtr	clc	adc #CloseParams	tax	lda <MemPtr+2	adc #0	pha	phx	pea CloseCall	jsl StackProDOS;----------------------------------------------------;; Set flag to indicate that clipboard is on disk;	ldy #ScrapState	lda #0	sta [<MemPtr],y;----------------------------------------------------;; Unlock the scrap table;	jsr UnlockFirstHandle;----------------------------------------------------;; Get rid of the memory copies of everything.;	jsr DisposeAllScraps	lda #0	; signal no error	clc	rtsERROR2	plx	; clean the stackERROR	pha	; save error code	jsr UnlockFirstHandle	pla	; get back error code	sec	; signal error	rts	ENDP	eject****************************************************************** WriteOutThisOne** Writes the scrap whose table entry is	pointed to by* PtrToThisOne to the open file.** If the scrap is larger than 64K it writes it out in 64K* pieces since ProDOS cannot handle any	more.** Returns any error	in a-reg.** Change History** 12 Aug 88	Steven Glass** The closefile call was pushing the wrong pointer* to the file ref num and leaving the file open.** Subsequent calls to read the scrap would fail because* of file aready open.* ****************************************************************	ENTRY WriteOutThisOneWriteOutThisOne	PROC	ldy #o_ScrapHandle	lda [<PtrToThisOne],y	sta <DestHandle	iny	iny	lda [<PtrToThisOne],y	sta <DestHandle+2	jsr DerefDest	lda <DestPtr	ldy #WriteFrom	sta [<MemPtr],y	lda <DestPtr+2	iny	iny	sta [<MemPtr],y	ldy #o_ScrapSize	lda [<PtrToThisOne],y	ldy #HowMuchToWrite	sta [<MemPtr],y	ldy #o_ScrapSize+2	lda [PtrToThisOne],y	ldy #HowMuchToWrite+2	sta [<MemPtr],y	ldy #HowMuchToWrite+2	lda [<MemPtr],y	ldy #WriteAmount+2	sta [<MemPtr],y	ldy #HowMuchToWrite	lda [<MemPtr],y	ldy #WriteAmount	sta [<MemPtr],y	lda <MemPtr	clc	adc #WriteParams	tax	lda <MemPtr+2	adc #0	pha	phx	pea WriteCall	jsl StackProDOSError	php	pha	jsr UnlockDest	pla	plp	rts	EndP	END